{
  "status": "SUPPORTED",
  "task_summary": "Prepare the living room for two people to enjoy refreshments while watching television. Provide each person with their own refreshment setting nearby, and place the entertainment control where it is accessible to both people.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_item",
        "entity_kind": "OBJECT",
        "function": "Holds or serves a drink or food for a person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "cup",
          "mug",
          "glass",
          "plate"
        ],
        "required_properties": [
          "holds liquid",
          "holds food"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television or media equipment.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "remote control",
          "controller"
        ],
        "required_properties": [
          "buttons",
          "electronic interface"
        ]
      },
      {
        "id": "placement_surface",
        "entity_kind": "REGION",
        "function": "Supports the refreshment items and entertainment control.",
        "required_count": 2,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "coffee table",
          "side table",
          "console table",
          "desk"
        ],
        "required_properties": [
          "flat top",
          "stable"
        ]
      },
      {
        "id": "seating_area",
        "entity_kind": "FIXED_TARGET",
        "function": "Location where the people sit.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "chair",
          "sofa",
          "armchair"
        ],
        "required_properties": [
          "upholstered",
          "wooden frame"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_location_relation",
        "relation": "is located on",
        "participant_roles": [
          "refreshment_item",
          "placement_surface"
        ]
      ,
      "required": true
      },
      {
        "id": "control_location_relation",
        "relation": "is located on",
        "participant_roles": [
          "entertainment_control",
          "placement_surface"
        ]
      ,
      "required": true
      },
      {
        "id": "proximity_relation",
        "relation": "is near",
        "participant_roles": [
          "placement_surface",
          "seating_area"
        ]
      ,
      "required": true
      },
      {
        "id": "accessibility_relation",
        "relation": "is accessible to",
        "participant_roles": [
          "entertainment_control",
          "seating_area"
        ]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "setup_refreshments",
        "operation": "move and arrange refreshment items onto placement surfaces",
        "participant_roles": [
          "refreshment_item",
          "placement_surface"
        ]
      ,
      "operation_count": 2
      },
      {
        "id": "setup_control",
        "operation": "place entertainment control on a placement surface",
        "participant_roles": [
          "entertainment_control",
          "placement_surface"
        ]
      ,
      "operation_count": 1
      }
    ]
  },
